from django.contrib import admin, messages

class OrderItemInline(admin.TabularInline):
    model = OrderItem
    extra = 0
    autocomplete_fields = ["product"]

@admin.register(Order)
class OrderAdmin(admin.ModelAdmin):
    list_display = ["id", "customer", "status", "total"]
    inlines = [OrderItemInline]
    actions = ["mark_paid"]

    @admin.action(description="Mark selected orders as paid")
    def mark_paid(self, request, queryset):
        updated = queryset.filter(status="pending").update(status="paid")
        self.message_user(request, f"Marked {updated} orders as paid.", messages.SUCCESS)

from django.contrib import admin

@admin.register(Post)
class PostAdmin(admin.ModelAdmin):
    def has_change_permission(self, request, obj=None):
        if obj is not None and obj.author_id != request.user.id:
            return request.user.is_superuser
        return super().has_change_permission(request, obj)

