from django.db.models import Count

@admin.register(Author)
class AuthorAdmin(admin.ModelAdmin):
    list_display = ["name", "post_count"]

    def get_queryset(self, request):
        return super().get_queryset(request).annotate(_post_count=Count("posts"))

    @admin.display(description="Posts", ordering="_post_count")
    def post_count(self, obj):
        return obj._post_count

from django.contrib import admin, messages

@admin.register(Invoice)
class InvoiceAdmin(admin.ModelAdmin):
    list_display = ("number", "customer", "total", "status")
    readonly_fields = ("number", "created_at", "created_by")
    actions = ("mark_paid",)

    def get_queryset(self, request):
        qs = super().get_queryset(request)
        if request.user.is_superuser:
            return qs
        return qs.filter(tenant=request.user.tenant)

    def has_delete_permission(self, request, obj=None):
        if obj and obj.status == "paid":
            return False
        return super().has_delete_permission(request, obj)

    @admin.action(description="Mark selected invoices paid")
    def mark_paid(self, request, queryset):
        if not self.has_change_permission(request):
            self.message_user(request, "Not allowed.", messages.ERROR)
            return
        updated = queryset.filter(status="open").update(status="paid")
        self.message_user(request, f"Marked {updated} invoices paid.")
